// =======================================================================
// 2D rendering into surfaces and the backbuffer: blits, fills and the
// triangle batches generated by sketchpads and 2D panels
// =======================================================================

#ifndef __DRAW2D_H
#define __DRAW2D_H

#include "VkContext.h"
#include "VkTexture.h"
#include <map>
#include <utility>
#include <vector>

/// 2D vertex: position in target pixels, texture coordinates (normalised,
/// or texels in fetch mode) and a linear-space colour multiplied with the texel
struct Vtx2D {
	float x, y, u, v;
	float r, g, b, a;
};

enum class Blend2D { Copy, Alpha, Additive };

struct DrawState2D {
	VkTexture *tex = nullptr;              ///< nullptr: untextured
	Blend2D blend = Blend2D::Alpha;
	bool fetch = false;                    ///< unfiltered texel fetch, uv in texels
	uint32_t ckey = VkTexture::NO_CKEY;    ///< discard texels of this colour (0xRRGGBB)
	VkRect2D clip{ {0, 0}, {0, 0} };       ///< scissor; zero extent: whole target

	bool operator== (const DrawState2D &s) const {
		return tex == s.tex && blend == s.blend && fetch == s.fetch && ckey == s.ckey &&
			clip.offset.x == s.clip.offset.x && clip.offset.y == s.clip.offset.y &&
			clip.extent.width == s.clip.extent.width && clip.extent.height == s.clip.extent.height;
	}
};

/// sRGB-encoded 8-bit channel to linear intensity
float SRGBToLinear (uint8_t c);
/// Colour 0xBBGGRR (GDI COLORREF) to linear RGBA
void ColorRefToLinear (uint32_t bgr, float alpha, float out[4]);
/// Colour 0xRRGGBB (device colour) to linear RGBA
void DeviceColorToLinear (uint32_t rgb, float alpha, float out[4]);

class Renderer2D {
public:
	bool Init (vkc::Context *ctx, TextureManager *texmgr);
	void Shutdown ();

	/// Select the render target for the following draws (nullptr: backbuffer,
	/// which is only available while a frame is being rendered). Converts the
	/// target to a render-target surface if required.
	bool Begin (VkTexture *tgt);
	VkTexture *Target () const { return target; }
	VkExtent2D TargetSize () const;

	/// Append triangles to the batch of the current target
	Vtx2D *AddTris (const DrawState2D &st, size_t nvtx);
	void Quad (const DrawState2D &st, float x0, float y0, float x1, float y1,
		float u0, float v0, float u1, float v1, const float col[4]);

	/// Record the pending batch
	void Flush ();

	bool Blit (VkTexture *tgt, int tx, int ty, int tw, int th,
		VkTexture *src, int sx, int sy, int sw, int sh, bool useCkey);
	bool Fill (VkTexture *tgt, int x, int y, int w, int h, uint32_t rgb);

	/// Make sure a surface can be rendered to (copies compressed or
	/// mipmapped textures into an RGBA8 render-target image)
	bool EnsureRenderTarget (VkTexture *tex);

private:
	VkPipeline Pipeline (VkFormat fmt, Blend2D blend);
	void BindCurrent ();
	bool CopyToScratch (VkTexture *src, int sx, int sy, int sw, int sh);

	vkc::Context *ctx = nullptr;
	TextureManager *texmgr = nullptr;
	VkPipelineLayout layout = VK_NULL_HANDLE;
	std::map<std::pair<VkFormat, Blend2D>, VkPipeline> pipelines;
	VkShaderModule vs = VK_NULL_HANDLE, fs = VK_NULL_HANDLE;

	VkTexture *target = nullptr;
	bool hasTarget = false;
	DrawState2D batchState;
	std::vector<Vtx2D> batch;

	VkTexture *scratch = nullptr; // copy of a source region for blits within a surface
};

#endif // !__DRAW2D_H
